import{At as e,Q as t,St as n,at as r,it as i,nt as a,ot as o,st as s,t as c,vt as l}from"./chunks/framework.B7aBQbI5.js";var u=JSON.parse(`{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"pages/overview.md"}`),d={name:`index.md`};function f(c,u,d,f,p,m){let h=n(`Mermaid`);return l(),i(`div`,null,[u[1]||=r(`<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h1><ul><li><a href="#what-grapht-is">What grapht is</a></li><li><a href="#the-pipeline">The pipeline</a></li><li><a href="#ingest">Ingest</a></li><li><a href="#canonical-model">Canonical model</a></li><li><a href="#renderers">Renderers</a></li><li><a href="#history-journal">History journal</a></li></ul><h2 id="what-grapht-is" tabindex="-1">What grapht is <a class="header-anchor" href="#what-grapht-is" aria-label="Permalink to “What grapht is”">​</a></h2><p><code>@hafley66/grapht</code> is a graph diagram toolkit. It ingests d2 and mermaid sources into one canonical, flat <code>Graph</code> model, renders that model through swappable renderer adapters, and journals git history for the graph over time.</p><table tabindex="0"><thead><tr><th>lane</th><th>package</th><th>what it owns</th></tr></thead><tbody><tr><td>ingest</td><td><code>@hafley66/d2</code>, <code>@hafley66/mmd</code></td><td>parse d2 and mermaid into the canonical model</td></tr><tr><td>model</td><td><code>@hafley66/grapht-model</code></td><td><code>Graph</code>, validation, indexes, sticky placement</td></tr><tr><td>frame</td><td><code>@hafley66/grapht</code></td><td>geometry, camera, presentation, renderer contract</td></tr><tr><td>history</td><td><code>@hafley66/grapht</code></td><td>offline journal, <code>grapht-history</code> CLI</td></tr><tr><td>render</td><td><code>adapters/*</code></td><td>project the model into Cytoscape, Pixi, Three, Sigma</td></tr></tbody></table><h2 id="the-pipeline" tabindex="-1">The pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to “The pipeline”">​</a></h2>`,6),(l(),a(t,null,{default:e(()=>[s(h,{id:`mermaid-116`,class:`mermaid`,graph:`flowchart%20LR%0A%20%20S%5B%22d2%20%2F%20mermaid%5Cnsource%22%5D%20--%3E%20P%5B%22parser%22%5D%0A%20%20P%20--%3E%20G%5B%22canonical%20Graph%20model%22%5D%0A%20%20G%20--%3E%20A%5B%22renderer%20adapters%22%5D%0A%20%20G%20--%3E%20J%5B%22git-history%20journal%22%5D%0A`})]),fallback:e(()=>[...u[0]||=[o(` Loading... `,-1)]]),_:1})),u[2]||=r(`<p>The durable model stays framework-free. Adapters project the same normalized entities into each renderer, so a receipt measured on one renderer is comparable against the others.</p><h2 id="ingest" tabindex="-1">Ingest <a class="header-anchor" href="#ingest" aria-label="Permalink to “Ingest”">​</a></h2><p>Parsers live in the <code>@hafley66/d2</code> and <code>@hafley66/mmd</code> packages. Each turns one source language into a sequence local document and an SVG binding, then the model normalizes that into a <code>Graph</code>.</p><h2 id="canonical-model" tabindex="-1">Canonical model <a class="header-anchor" href="#canonical-model" aria-label="Permalink to “Canonical model”">​</a></h2><p><code>Graph</code> is a flat record of <code>GraphNode</code> and <code>GraphEdge</code> keyed by <code>GraphId</code>. The <a href="./model">model</a> page shows one real literal and what <code>validateGraph</code> rejects.</p><h2 id="renderers" tabindex="-1">Renderers <a class="header-anchor" href="#renderers" aria-label="Permalink to “Renderers”">​</a></h2><p>The renderer contract is <code>GraphFrameResource</code>, one <code>render(frame, receipt)</code> call plus an <code>unsubscribe</code>. The <a href="./renderers">renderers</a> page lists the adapters and the gestures the document renderer answers.</p><h2 id="history-journal" tabindex="-1">History journal <a class="header-anchor" href="#history-journal" aria-label="Permalink to “History journal”">​</a></h2><p><code>grapht-history</code> walks git and writes a self-contained JSONL journal, one revision per line with a content hash. The <a href="./history">history</a> page covers the format and verification.</p><h2 id="planned-interactions" tabindex="-1">Planned interactions <a class="header-anchor" href="#planned-interactions" aria-label="Permalink to “Planned interactions”">​</a></h2><p><a href="./roadmap">Feature status</a> separates the planned interaction experience from existing components. Each proposal links its source evidence, open decisions, and acceptance checks.</p>`,11)])}var p=c(d,[[`render`,f]]);export{u as __pageData,p as default};